function validate([edges, values]) {
  const n = values.length;
  if (n < 2 || n > 20000) return 'The tree needs 2 to 2 * 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000000000)) return 'Each value is an integer from 1 to 10^9.';
  if (edges.length !== n - 1) return 'edges must have exactly n - 1 pairs.';
  const root = Array.from({ length: n }, (_, i) => i);
  const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
  for (const e of edges) {
    if (!Array.isArray(e) || e.length !== 2 || !e.every(v => Number.isInteger(v) && v >= 0 && v < n)) return 'Each edge is a pair of node labels from 0 to n - 1.';
    const ra = find(e[0]), rb = find(e[1]);
    if (ra === rb) return 'edges must form a tree (no cycles or self-loops).';
    root[ra] = rb;
  }
  return null;
}

