function maximumScoreAfterOperations(edges, values) {
  const n = values.length;
  const graph = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }
  const parent = new Array(n).fill(-1);
  const order = [0];
  for (let i = 0; i < order.length; i++) {
    const node = order[i];
    for (const next of graph[node]) {
      if (next !== parent[node]) {
        parent[next] = node;
        order.push(next);
      }
    }
  }
  const keep = new Array(n).fill(0);
  const childKeep = new Array(n).fill(0);
  let total = 0;
  for (let i = n - 1; i >= 0; i--) {
    const node = order[i];
    total += values[node];
    const isLeaf = node !== 0 && graph[node].length === 1;
    keep[node] = isLeaf ? values[node] : Math.min(values[node], childKeep[node]);
    if (node !== 0) {
      childKeep[parent[node]] += keep[node];
    }
  }
  return total - keep[0];
}

