function maximumScoreAfterOperations(edges, values) {
  const n = values.length;
  const adj = Array.from({ length: n }, () => []);
  for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }
  const paths = [];
  const walk = (node, from, path) => {
    const below = adj[node].filter(x => x !== from);
    if (below.length === 0) paths.push([...path, node]);
    for (const child of below) walk(child, node, [...path, node]);
  };
  walk(0, -1, []);
  let best = 0;
  for (let picked = 0; picked < 1 << n; picked++) {
    const now = values.map((v, i) => (picked >> i) & 1 ? 0 : v);
    if (!paths.every(p => p.reduce((s, v) => s + now[v], 0) !== 0)) continue;
    let score = 0;
    for (let i = 0; i < n; i++) if ((picked >> i) & 1) score += values[i];
    best = Math.max(best, score);
  }
  return best;
}

